280	private fun openSettings(context: Context, action: String, packageName: String? = null) {
281	    val intent = Intent(action)
282	    packageName?.let { intent.putExtra(Settings.EXTRA_APP_PACKAGE, it) }
283	    if (action == Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS) {
284	        intent.putExtra(Settings.EXTRA_CHANNEL_ID, "farhan_breakthrough_notifications")
285	    }
286	    try {
287	        context.startActivity(intent)
288	    } catch (_: ActivityNotFoundException) {
289	        context.startActivity(Intent(Settings.ACTION_SETTINGS))
290	    }
291	}
