293	private fun describe(state: SoundControlState): String = when (state) {
294	    SoundControlState.Off -> "Farhan’s rule is off"
295	    SoundControlState.Creating -> "Turning on Farhan’s rule"
296	    is SoundControlState.Held -> "Farhan’s rule is on"
297	    is SoundControlState.Suspended -> when (state.reason) {
298	        SuspensionReason.FILTER_OFF -> "Turn on the notification filter before resuming."
299	        SuspensionReason.APP_OFF -> "Turn on Farhan’s main switch before resuming."
300	        SuspensionReason.LISTENER_ACCESS -> "Notification access is off."
301	        SuspensionReason.NEEDS_ACCESS -> "Do Not Disturb access is off. Open Android Modes if Farhan’s rule is still on."
302	        SuspensionReason.POST_PERMISSION -> "Permission to post notifications is off."
303	        SuspensionReason.CHANNEL_UNUSABLE -> "Farhan’s alert channel cannot override Do Not Disturb. Check its settings."
